class Solution:
    def minOperationsToSortString(self, s):
        n = len(s)
        if all(s[i] <= s[i + 1] for i in range(n - 1)): return 0
        if n == 2: return -1
        if all(s[i] > s[i + 1] for i in range(n - 1)): return -1
        return sum(1 for i in range(n - 1) if s[i] > s[i + 1])

c.cpp:
class Solution {
public:
    int minOperationsToSortString(string s) {
        int n = s.size();
        bool sortedAsc = true, allDesc = true;
        for (int i = 0; i + 1 < n; i++) {
            if (s[i] > s[i + 1]) sortedAsc = false; else allDesc = false;
        }
        if (sortedAsc) return 0;
        if (n == 2) return -1;
        if (allDesc) return -1;
        int ans = 0;
        for (int i = 0; i + 1 < n; i++) if (s[i] > s[i + 1]) ans++;
        return ans;
    }
};

