class Solution {
    public int minOperationsToSortString(String s) {
        int n = s.length();
        boolean sortedAsc = true, allDesc = true;
        for (int i = 0; i + 1 < n; i++) {
            if (s.charAt(i) > s.charAt(i + 1)) sortedAsc = false; else allDesc = false;
        }
        if (sortedAsc) return 0;
        if (n == 2) return -1;
        if (allDesc) return -1;
        int ans = 0;
        for (int i = 0; i + 1 < n; i++) if (s.charAt(i) > s.charAt(i + 1)) ans++;
        return ans;
    }
}

